import LANDING_DATES from "@/lib/landingDates.json";
import { EXAM_LANDINGS_UPDATED_AT } from "@/lib/seoDates";

// The last commit date of each exam's landing, bank and translated copy,
// generated by scripts/build-landing-dates.ts (Vercel's shallow clones have no
// history to read at build time). Sitemap <lastmod> and each landing's
// dateModified use it so exams only claim a change when they had one.
const DATES = LANDING_DATES as Record<string, string>;

/** ISO date an exam's landing last changed; EXAM_LANDINGS_UPDATED_AT for an exam not in the map yet. */
export function landingUpdatedAt(examId: string): string {
  return DATES[examId] ?? EXAM_LANDINGS_UPDATED_AT;
}

/** The newest of every landing's date, for the sitemap index. */
export function latestLandingUpdate(): string {
  return Object.values(DATES).sort().at(-1) ?? EXAM_LANDINGS_UPDATED_AT;
}
